actions.script:
const out = ec.service.sync().name('ironstone.shared.ChatterServices.get#ChatterData').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || ''}).call()
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else if (!out.visible) ec.web.sendJsonResponse({visible: false})
else ec.web.sendJsonResponse({visible: true, record: out.record, me: out.me, forClient: out.forClient, canMessage: out.canMessage, canSchedule: out.canSchedule,
    mayUpdate: out.mayUpdate, followerList: out.followerList, isFollowing: out.isFollowing, myKinds: out.myKinds,
    plannedActivities: out.plannedActivities, fileList: out.fileList, fileCount: out.fileCount, hasContent: out.hasContent,
    partyList: out.partyList, failedSources: out.failedSources})

const out = partyId ? ec.service.sync().name('ironstone.commons.ContactServices.get#ContactAvatar').parameters({partyId: partyId}).call() : null
if (out?.contentLocation) ec.web.sendResourceResponse(out.contentLocation, true)
else ec.web.sendJsonError(404, ec.l10n.localize('No picture'))

const out = ec.service.sync().name('ironstone.shared.RecordFilesServices.get#RecordFile').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || '', contentKey: contentKey || ''}).call()
if (!ec.message.hasError() && !out.contentLocation) ec.message.addError(ec.l10n.localize('This file has no content'))
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.contentLocation, String(inline) === 'true' && out.inlineAllowed)

const out = ec.service.sync().name('ironstone.shared.ChatterServices.get#Attachment').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || '', communicationEventContentId: communicationEventContentId || ''}).call()
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.contentLocation, String(inline) === 'true' && out.inlineAllowed)

const forClient = !!ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')
const out = ec.service.sync().name(forClient ? 'ironstone.client.ClientServices.reply#ChatterMessage' : 'ironstone.shared.ChatterServices.reply#Entry')
    .parameters({recordEntityName: recordEntity, recordId: recordId, parentCommEventId: parentCommEventId, body: body, recordUrl: recordUrl || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {communicationEventId: out.communicationEventId,
    messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.shared.ChatterServices.edit#Entry').parameters({recordEntityName: recordEntity, recordId: recordId,
    communicationEventId: communicationEventId, body: body, recordUrl: recordUrl || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {mentionedUserIds: out.mentionedUserIds, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.shared.ChatterServices.delete#Entry').parameters({recordEntityName: recordEntity, recordId: recordId,
    communicationEventId: communicationEventId}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {deleted: out.deleted, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.shared.ChatterServices.cancel#Activity').parameters({recordEntityName: recordEntity, recordId: recordId,
    workEffortId: workEffortId}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.shared.ChatterServices.follow#Record').parameters({recordEntityName: recordEntity, recordId: recordId,
    kinds: kinds || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.shared.ChatterServices.unfollow#Record').parameters({recordEntityName: recordEntity, recordId: recordId,
    userId: userId || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.shared.ChatterServices.add#Followers').parameters({recordEntityName: recordEntity, recordId: recordId,
    userIds: userIds || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {addedUserIds: out.addedUserIds, messageInfos: [{type: 'success', message: out.message}]})
